<script setup>
import { ref, computed, nextTick, onMounted, onBeforeUnmount, watch } from 'vue'
import L from 'leaflet'
import { Map, MapPin, Compass, Mail, ArrowUpRight, ArrowRight, Heart, MessageCircle, Send, CalendarDays, Users, Leaf, Trophy, LockKeyhole, Check, Navigation, Search, Bell, Sparkles, X, ChevronRight, Ticket, LocateFixed } from 'lucide-vue-next'
const tabs = [{id:'mapa',label:'Explorar',icon:Compass},{id:'convite',label:'Convites',icon:Mail},{id:'feed',label:'Feed do lugar',icon:MapPin}]
const screen = ref(tabs.some(t=>t.id===location.hash.slice(1)) ? location.hash.slice(1) : 'mapa')
const filter=ref('Todos'), search=ref(''), accepted=ref(false), arrived=ref(false), toast=ref('')
const posts = ref([
 {id:1, image:'/jardim-botanico.jpg', alt:'Estufa e jardins do Jardim Botânico de Curitiba', name:'Lia Martins', initials:'LM', avatar:'lia', time:'há 1h', likes:24, liked:false, showComments:false, comment:'', comments:[{name:'Pedro Santos',text:'Esse lugar nunca perde a graça! 🌿'}], caption:'Esse fim de tarde :) Às vezes, tudo o que a gente precisa é sair um pouco da rotina. Curitiba, você é linda! 💚', tags:'#JardimBotânico #BoraLá #Curitiba', note:'Uma pausa que valeu a pena'},
 {id:2, image:'/jardim-botanico-flores.jpg', alt:'Flores nos jardins do Jardim Botânico de Curitiba', name:'Lucas Costa', initials:'LC', avatar:'lucas', time:'há 2h', likes:18, liked:false, showComments:false, comment:'', comments:[{name:'Lia Martins',text:'Na próxima eu vou junto! ☀️'}], caption:'Troquei uma hora de tela por uma caminhada por aqui. Melhor escolha do sábado! Quem vem na próxima? 🌿', tags:'#AoArLivre #BoraJunto #Curitiba', note:'Um passeio para repetir'}
])
let toastTimer, map, markers=[]
const places=[
 {id:1,name:'Jardim Botânico',category:'Natureza',lat:-25.4429,lng:-49.2388,event:'Um sábado mais verde',time:'Sáb, 14 nov · 15h',points:50,description:'Encontre seus amigos e redescubra um dos lugares mais queridos de Curitiba.',icon:'🌿'},
 {id:2,name:'Parque Barigui',category:'Esporte',lat:-25.4266,lng:-49.3078,event:'Movimente-se no parque',time:'Dom, 15 nov · 9h',points:30,description:'Uma caminhada ao ar livre para começar o domingo com energia.',icon:'☀'},
 {id:3,name:'Largo da Ordem',category:'Cultura',lat:-25.4248,lng:-49.2714,event:'Domingo de feirinha',time:'Dom, 15 nov · 10h',points:20,description:'Arte, encontros e sabores no coração histórico da cidade.',icon:'🎨'},
 {id:4,name:'Museu Oscar Niemeyer',category:'Cultura',lat:-25.4099,lng:-49.2673,event:'Um novo olhar para a arte',time:'Sáb, 14 nov · 14h',points:40,description:'Um passeio para se inspirar e conversar sobre novas descobertas.',icon:'▧'}]
const selected=ref(places[0])
const visible=computed(()=>places.filter(p=>(filter.value==='Todos'||p.category===filter.value)&&`${p.name} ${p.event}`.toLocaleLowerCase('pt-BR').includes(search.value.toLocaleLowerCase('pt-BR'))))
function notify(text){toast.value=text;clearTimeout(toastTimer);toastTimer=setTimeout(()=>toast.value='',4500)}
async function navigate(id){screen.value=id;location.hash=id;await nextTick();if(id==='mapa'){if(!map)initMap();else map.invalidateSize()}}
function syncHash(){const id=location.hash.slice(1);if(tabs.some(t=>t.id===id))navigate(id)}
function selectPlace(p){selected.value=p;map?.flyTo([p.lat,p.lng],13,{duration:.6});markers.find(m=>m.placeId===p.id)?.openPopup()}
function updateMarkers(){if(!map)return;markers.forEach(m=>m.remove());markers=visible.value.map(p=>{const m=L.marker([p.lat,p.lng],{icon:L.divIcon({className:'bora-marker',html:`<span>${p.icon}</span>`,iconSize:[44,44],iconAnchor:[22,44]})}).addTo(map);m.placeId=p.id;const box=document.createElement('div');box.className='map-popup';const name=document.createElement('strong');name.textContent=p.name;const desc=document.createElement('p');desc.textContent=p.event;const info=document.createElement('small');info.textContent=p.time+' · +'+p.points+' pontos';box.append(name,desc,info);m.bindPopup(box);m.on('click',()=>selected.value=p);return m})}
function initMap(){map=L.map('city-map',{zoomControl:false,scrollWheelZoom:false}).setView([-25.4284,-49.272],12);L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',{attribution:'&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a>',maxZoom:19}).addTo(map);L.control.zoom({position:'topright'}).addTo(map);updateMarkers()}
watch(visible,updateMarkers)
function addComment(post){if(!post.comment.trim())return;post.comments.push({name:'Ana Lima',text:post.comment.trim()});post.comment=''}
function checkIn(){arrived.value=true;notify('Você chegou! História desbloqueada e +50 pontos na sua conta.')}
async function viewGarden(){filter.value='Todos';search.value='';await navigate('mapa');selectPlace(places[0])}
onMounted(()=>{if(screen.value==='mapa')initMap();window.addEventListener('hashchange',syncHash)})
onBeforeUnmount(()=>{map?.remove();clearTimeout(toastTimer);window.removeEventListener('hashchange',syncHash)})
</script>

<template>
<div class="app-shell">

 <div class="main-shell">
  <header class="topbar"><a class="header-brand" href="#mapa" @click.prevent="navigate('mapa')" aria-label="Curitiba APP — início"><img src="/curitiba-app-logo.png" alt="Curitiba APP" width="180" height="63"/></a><div class="top-actions"><span class="demo-pill"><span/> Protótipo interativo</span><button class="notification icon-button" aria-label="Ver convite recebido" @click="navigate('convite')"><Bell :size="20"/><i v-if="!accepted"/></button><span class="avatar me">AL</span><span class="user-name">Ana Lima</span></div></header>
  <main>
   <section v-show="screen==='mapa'" class="screen explore">
    <div class="page-heading"><div><div class="eyebrow"><span/> CURITIBA, PARANÁ</div><h1>Bora explorar?</h1><p>Seu próximo encontro está aqui.</p></div><div class="points-pill"><Trophy :size="19"/><strong>{{arrived?170:120}}</strong><span>pontos</span></div></div>
    <div class="explore-grid"><div class="map-column"><div class="map-toolbar"><label class="search"><Search :size="19"/><input v-model="search" placeholder="Buscar lugar ou evento" aria-label="Buscar lugares"/></label><div class="filters"><button v-for="f in ['Todos','Natureza','Cultura','Esporte']" :key="f" :class="{selected:filter===f}" @click="filter=f">{{f}}</button></div></div><div class="map-wrap"><div id="city-map" aria-label="Mapa de Curitiba com eventos"/><div class="map-label"><span class="live-dot"/> A cidade acontece aqui</div><button class="locate icon-button" aria-label="Centralizar mapa em Curitiba" @click="map?.setView([-25.4284,-49.272],12)"><LocateFixed :size="22"/></button></div><div class="map-foot"><span><MapPin :size="15"/> {{visible.length}} lugares para descobrir</span><span>Explore. Encontre. Viva.</span></div></div>
    <aside class="discovery-panel"><div class="section-heading"><h2>Perto de você</h2><span>EM CURITIBA</span></div><div class="place-list"><button v-for="p in visible" :key="p.id" class="place-item" :class="{chosen:selected.id===p.id}" @click="selectPlace(p)"><span class="place-emoji" :class="p.category">{{p.icon}}</span><span><strong>{{p.name}}</strong><small>{{p.event}}</small><span class="place-meta">{{p.category}} <b>+{{p.points}} pts</b></span></span><ChevronRight :size="17"/></button><p v-if="!visible.length" class="empty">Nenhum lugar encontrado. Tente outra busca.</p></div><div class="selected-event"><span class="tag"><Sparkles :size="13"/> BORA NESSE?</span><h3>{{selected.event}}</h3><p>{{selected.description}}</p><span class="event-time"><CalendarDays :size="16"/>{{selected.time}}</span><button class="primary" @click="selected.id===1?navigate('convite'):notify(`${selected.event}: ${selected.time}, em ${selected.name}. Evento demonstrativo.`)">{{selected.id===1?'Ver convite':'Ver evento'}}<ArrowUpRight :size="18"/></button></div></aside></div>
    <button class="invitation-banner" @click="navigate('convite')"><span class="banner-icon"><Mail :size="24"/></span><span><strong>Lucas te chamou. Bora?</strong><small>Jardim Botânico · sábado, 15h</small></span><span class="banner-link">Abrir convite <ArrowRight :size="18"/></span></button>
   </section>
   <section v-if="screen==='convite'" class="screen invitation-screen"><div class="page-heading"><div><div class="eyebrow">ENTRE AMIGOS</div><h1>Bora junto?</h1><p>Um convite para sair da rotina.</p></div><span class="soft-label"><Mail :size="16"/> Convite entre amigos</span></div><div class="invitation-layout"><div class="invitation-photo"><img src="/jardim-botanico.jpg" alt="Estufa de vidro e jardins do Jardim Botânico de Curitiba"/><div class="photo-shade"/><span class="photo-badge"><MapPin :size="15"/> CURITIBA, PR</span><div class="photo-caption"><span>AO AR LIVRE</span><h2>Jardim <br>Botânico</h2><p>Curitiba, ao ar livre.</p></div></div><div class="invitation-content"><span class="tag blue"><Mail :size="14"/> CONVITE PARA VOCÊ</span><div class="inviter"><span class="avatar lucas">LC</span><span><strong>Lucas Costa</strong><small>te convidou</small></span><span class="sent-time">há 20 min</span></div><h2><span>Bora sábado?</span></h2><p class="invite-message">“Ana, bora passear e colocar o papo em dia? 🌿”</p><div class="invite-facts"><div><MapPin/><span><small>ONDE</small><strong>Jardim Botânico Municipal</strong><p>R. Eng. Ostoja Roguski, 350 · Curitiba</p></span></div><div><CalendarDays/><span><small>QUANDO</small><strong>Sáb, 14 nov · 15h</strong></span></div></div><div class="reward-note"><Trophy :size="22"/><span><strong>+50 pontos por essa visita</strong><small>Campanha demonstrativa</small></span></div><button class="primary accept-button" @click="accepted=true;notify('Presença confirmada! Lucas vai adorar te encontrar.')"><Check v-if="accepted" :size="20"/><span>{{accepted?'Presença confirmada':'Eu vou. Bora!'}}</span><ArrowRight v-if="!accepted" :size="20"/></button><button class="text-button" @click="viewGarden"><Map :size="16"/> Ver lugar no mapa</button><p class="private-note"><LockKeyhole :size="13"/> Só entre você e Lucas.</p></div></div></section>
   <section v-if="screen==='feed'" class="screen feed-screen"><div class="page-heading"><div><div class="eyebrow"><MapPin :size="13"/> HISTÓRIAS QUE PERTENCEM A ESTE LUGAR</div><h1>Jardim Botânico</h1><p>Quem passa por aqui deixa um pouquinho de si.</p></div><button class="outline-button" @click="viewGarden"><Map :size="16"/> Ver no mapa</button></div><div class="feed-layout"><div class="feed-column"><div class="feed-tabs"><span class="active"><Users :size="17"/> Amigos <b>{{posts.length}}</b></span><span class="feed-context">{{posts.length}} histórias para descobrir</span></div><article v-for="post in posts" :key="post.id" class="post"><div class="post-header"><span class="avatar" :class="post.avatar">{{post.initials}}</span><div><strong>{{post.name}}</strong><small><MapPin :size="12"/> Jardim Botânico · {{post.time}}</small></div><span class="friends-label"><Users :size="13"/> Amigos</span></div><div class="post-image"><img :src="post.image" :alt="post.alt" :class="{locked:!arrived}"/><span v-if="arrived" class="unlocked-label"><Check :size="14"/> Você está neste lugar</span><div v-else class="locked-overlay"><span class="lock-circle"><LockKeyhole :size="28"/></span><h2>Essa história está aqui.</h2><p>Vá ao Jardim Botânico para<br>descobrir o que {{post.name}} compartilhou.</p><button @click="checkIn" class="primary"><Navigation :size="17"/> Simular chegada ao local</button><small>Demonstração · nenhuma localização é coletada</small></div></div><div v-if="arrived" class="post-body"><div class="post-actions"><button :class="{liked:post.liked}" :aria-pressed="post.liked" @click="post.liked=!post.liked"><Heart :size="22" :fill="post.liked?'currentColor':'none'"/>{{post.likes + (post.liked ? 1 : 0)}}</button><button @click="post.showComments=!post.showComments" :aria-expanded="post.showComments"><MessageCircle :size="22"/>{{post.comments.length}}</button><span class="post-location"><Leaf :size="15"/> {{post.note}}</span></div><p><strong>{{post.name}}</strong> {{post.caption}}</p><span class="hashtags">{{post.tags}}</span><div v-if="post.showComments" class="comments"><p v-for="(c,i) in post.comments" :key="i"><strong>{{c.name}}</strong> {{c.text}}</p><form @submit.prevent="addComment(post)"><input v-model="post.comment" maxlength="500" placeholder="Deixe um comentário…" aria-label="Seu comentário"/><button type="submit" aria-label="Enviar comentário" :disabled="!post.comment.trim()"><Send :size="18"/></button></form></div></div><div v-else class="locked-footer"><LockKeyhole :size="16"/> Algumas histórias merecem ser vividas de perto.</div></article><p class="fiction-note">Perfis e publicações fictícios, criados para esta demonstração.</p></div><aside class="feed-sidebar"><div class="visit-card"><span class="visit-icon"><component :is="arrived?Check:MapPin" :size="26"/></span><span class="eyebrow">{{arrived?'BOA DESCOBERTA!':'O LUGAR É A CHAVE'}}</span><h2>{{arrived?'Chegou. Desbloqueou.':'A cidade se abre para quem vai.'}}</h2><p>{{arrived?'Agora você faz parte dessa história. Curta, comente e aproveite o momento.':'As publicações dos seus amigos esperam por você nos lugares onde aconteceram.'}}</p><div class="visit-status"><span :class="{green:arrived}"/>{{arrived?'Presença simulada confirmada':'Você ainda não está neste lugar'}}</div><button v-if="arrived" class="text-button" @click="arrived=false;notify('Demonstração reiniciada.')">Reiniciar demonstração</button></div><div class="points-card"><div><Trophy :size="21"/><span>SUAS DESCOBERTAS VALEM</span></div><strong>{{arrived?170:120}} <small>pontos</small></strong><div class="progress-track"><span :style="{width:(arrived?68:48)+'%'}"/></div><p>Faltam {{arrived?80:130}} pontos para sua próxima conquista.</p><span class="reward-preview"><Ticket :size="18"/> Vale-lanche · 250 pontos</span><small class="mock-note">Recompensa ilustrativa, sem valor real.</small></div></aside></div></section>
   <footer class="page-footer"><span>Partiu · A cidade é o seu feed.</span><span>Protótipo · Sem integração oficial</span></footer>
  </main>
 </div>
 <nav class="mobile-nav" aria-label="Navegação mobile"><button v-for="tab in tabs" :key="tab.id" :class="{active:screen===tab.id}" @click="navigate(tab.id)"><component :is="tab.icon" :size="21"/>{{tab.label}}</button></nav>
 <Transition name="toast"><div v-if="toast" class="toast-message" role="status"><Check :size="19"/>{{toast}}<button aria-label="Fechar aviso" @click="toast='' "><X :size="16"/></button></div></Transition>
</div>
</template>
